-- Restrictive scope policies intersect previous permissive reader policies.
DROP POLICY IF EXISTS portal_reader_scope ON public.document_versions;
CREATE POLICY portal_reader_scope ON public.document_versions AS RESTRICTIVE FOR SELECT TO aicte_api_reader USING (EXISTS(SELECT 1 FROM public.documents d WHERE d.id=document_id));
DROP POLICY IF EXISTS portal_reader_scope ON public.documents;
CREATE POLICY portal_reader_scope ON public.documents AS RESTRICTIVE FOR SELECT TO aicte_api_reader USING (api_private.can_read('institution.read',institution_id,NULL) OR api_private.can_read('application.read',institution_id,application_id));
